namespace sv_9f8e48d1a3a948449c7600ecf734d213.Services;

public class WarehouseState
{
    private string _selectedWarehouseId = "WH-A";

    public string SelectedWarehouseId => _selectedWarehouseId;

    public string SelectedWarehouseName =>
        Warehouses.FirstOrDefault(w => w.Id == _selectedWarehouseId)?.Name ?? "Unknown";

    public static IReadOnlyList<WarehouseInfo> Warehouses { get; } =
    [
        new("WH-A", "Warehouse A — Main Distribution"),
        new("WH-B", "Warehouse B — East Coast"),
        new("WH-C", "Warehouse C — West Coast"),
        new("WH-D", "Warehouse D — Cold Storage"),
    ];

    public event Action? OnChange;

    public void SetWarehouse(string warehouseId)
    {
        if (_selectedWarehouseId == warehouseId) return;
        _selectedWarehouseId = warehouseId;
        OnChange?.Invoke();
    }
}

public record WarehouseInfo(string Id, string Name);

namespace sv_9f8e48d1a3a948449c7600ecf734d213.Services;

/// <summary>
/// Scoped service that tracks low-stock alert counts per warehouse.
/// Provides polling control and a notification event so all subscribed
/// components update when new data arrives.
/// </summary>
public class InventoryAlertService : IDisposable
{
    private readonly WarehouseState _warehouseState;
    private readonly Random _random = new();
    private PeriodicTimer? _timer;
    private CancellationTokenSource? _cts;
    private int _subscriberCount;

    public int CurrentLowStockCount { get; private set; }

    /// <summary>
    /// Fired when polling retrieves new alert data.
    /// Subscribers must wrap StateHasChanged in InvokeAsync since this
    /// fires from a background thread.
    /// </summary>
    public event Action? OnAlertDataChanged;

    public InventoryAlertService(WarehouseState warehouseState)
    {
        _warehouseState = warehouseState;
        _warehouseState.OnChange += OnWarehouseChanged;
    }

    /// <summary>
    /// Simulates a database query returning low-stock item count.
    /// </summary>
    public Task<int> GetLowStockCountAsync(string warehouseId)
    {
        return Task.FromResult(_random.Next(0, 16));
    }

    /// <summary>
    /// Call when a component wants polling to be active.
    /// Polling starts on first subscriber and stops when all unsubscribe.
    /// </summary>
    public void StartPolling()
    {
        _subscriberCount++;
        if (_subscriberCount == 1)
        {
            _cts = new CancellationTokenSource();
            _timer = new PeriodicTimer(TimeSpan.FromSeconds(10));
            _ = PollLoopAsync(_cts.Token);
        }
    }

    /// <summary>
    /// Call when a component no longer needs polling (e.g., leaving a page).
    /// </summary>
    public void StopPolling()
    {
        _subscriberCount = Math.Max(0, _subscriberCount - 1);
        if (_subscriberCount == 0)
        {
            CancelPolling();
        }
    }

    /// <summary>
    /// Forces an immediate refresh of alert data and notifies subscribers.
    /// </summary>
    public async Task RefreshAsync()
    {
        CurrentLowStockCount = await GetLowStockCountAsync(_warehouseState.SelectedWarehouseId);
        OnAlertDataChanged?.Invoke();
    }

    private async Task PollLoopAsync(CancellationToken ct)
    {
        // Fetch immediately on start
        await RefreshAsync();

        while (!ct.IsCancellationRequested)
        {
            try
            {
                if (_timer is null || !await _timer.WaitForNextTickAsync(ct))
                    break;

                await RefreshAsync();
            }
            catch (OperationCanceledException)
            {
                break;
            }
        }
    }

    private async void OnWarehouseChanged()
    {
        // When warehouse changes, immediately refresh data
        if (_subscriberCount > 0)
        {
            await RefreshAsync();
        }
    }

    private void CancelPolling()
    {
        _cts?.Cancel();
        _cts?.Dispose();
        _cts = null;
        _timer?.Dispose();
        _timer = null;
    }

    public void Dispose()
    {
        _warehouseState.OnChange -= OnWarehouseChanged;
        CancelPolling();
    }
}

