@rendermode InteractiveServer
@inject sv_9f8e48d1a3a948449c7600ecf734d213.Services.WarehouseState WarehouseState
@implements IDisposable

<div class="warehouse-selector">
    <label class="form-label mb-0 me-2 text-white" for="warehouseSelect">Site:</label>
    <select id="warehouseSelect"
            class="form-select form-select-sm"
            style="width: auto; display: inline-block;"
            value="@WarehouseState.SelectedWarehouseId"
            @onchange="OnWarehouseChanged">
        @foreach (var wh in sv_9f8e48d1a3a948449c7600ecf734d213.Services.WarehouseState.Warehouses)
        {
            <option value="@wh.Id">@wh.Name</option>
        }
    </select>
</div>

@code {
    protected override void OnInitialized()
    {
        WarehouseState.OnChange += OnStateChanged;
    }

    private void OnWarehouseChanged(ChangeEventArgs e)
    {
        var newId = e.Value?.ToString();
        if (!string.IsNullOrEmpty(newId))
        {
            WarehouseState.SetWarehouse(newId);
        }
    }

    private void OnStateChanged() => InvokeAsync(StateHasChanged);

    public void Dispose()
    {
        WarehouseState.OnChange -= OnStateChanged;
    }
}

@rendermode InteractiveServer
@inject sv_9f8e48d1a3a948449c7600ecf734d213.Services.InventoryAlertService AlertService
@implements IDisposable

<span class="alert-badge position-relative">
    <span class="bi bi-exclamation-triangle-fill-nav-menu" aria-hidden="true"></span> Alerts
    @if (AlertService.CurrentLowStockCount > 0)
    {
        <span class="badge bg-danger rounded-pill ms-1">@AlertService.CurrentLowStockCount</span>
    }
    else
    {
        <span class="badge bg-success rounded-pill ms-1">0</span>
    }
</span>

@code {
    private Action? _handler;

    protected override void OnInitialized()
    {
        _handler = () => InvokeAsync(StateHasChanged);
        AlertService.OnAlertDataChanged += _handler;
    }

    public void Dispose()
    {
        if (_handler is not null)
        {
            AlertService.OnAlertDataChanged -= _handler;
        }
    }
}

@page "/dashboard"
@rendermode InteractiveServer
@inject sv_9f8e48d1a3a948449c7600ecf734d213.Services.WarehouseState WarehouseState
@inject sv_9f8e48d1a3a948449c7600ecf734d213.Services.InventoryAlertService AlertService
@implements IDisposable

<PageTitle>Warehouse Dashboard</PageTitle>

<h1>Warehouse Dashboard</h1>

<div class="card mb-4">
    <div class="card-header">
        <strong>Current Site:</strong> @WarehouseState.SelectedWarehouseName
    </div>
    <div class="card-body">
        <h5 class="card-title">Low-Stock Alerts</h5>
        <p class="card-text">
            @if (AlertService.CurrentLowStockCount > 0)
            {
                <span class="text-danger fw-bold">
                    ⚠️ @AlertService.CurrentLowStockCount item(s) below minimum stock level
                </span>
            }
            else
            {
                <span class="text-success fw-bold">
                    ✅ All items are adequately stocked
                </span>
            }
        </p>
        <p class="text-muted small">
            Auto-refreshes every 10 seconds. Last update: @_lastRefresh.ToString("HH:mm:ss")
        </p>
        <button class="btn btn-outline-primary btn-sm" @onclick="ManualRefresh">
            Refresh Now
        </button>
    </div>
</div>

@code {
    private DateTime _lastRefresh = DateTime.Now;
    private Action? _alertHandler;
    private Action? _warehouseHandler;

    protected override void OnInitialized()
    {
        _alertHandler = () => InvokeAsync(() =>
        {
            _lastRefresh = DateTime.Now;
            StateHasChanged();
        });

        _warehouseHandler = () => InvokeAsync(StateHasChanged);

        AlertService.OnAlertDataChanged += _alertHandler;
        WarehouseState.OnChange += _warehouseHandler;

        // Start polling when the dashboard becomes visible
        AlertService.StartPolling();
    }

    private async Task ManualRefresh()
    {
        await AlertService.RefreshAsync();
        _lastRefresh = DateTime.Now;
    }

    public void Dispose()
    {
        // Stop polling when leaving the dashboard
        AlertService.StopPolling();

        if (_alertHandler is not null)
            AlertService.OnAlertDataChanged -= _alertHandler;
        if (_warehouseHandler is not null)
            WarehouseState.OnChange -= _warehouseHandler;
    }
}

